#include <vector>
#include <numeric>
constexpr int sum_squares(int n) {
  std::vector<int> v(n);
  std::iota(v.begin(), v.end(), 1);
  int s = 0;
  for (int x : v) s += x * x;
  return s;
}
static_assert(sum_squares(3) == 14);
int main() { std::println("{}", sum_squares(4)); }

