#include <print>
int iroot(const int x)
  pre (x >= 0)
  post (r : r * r <= x)
{
  int r = 0;
  while ((r + 1) * (r + 1) <= x) ++r;
  return r;
}
int main() { std::println("{}", iroot(30)); }

#include <print>
#include <vector>
constexpr int max_tripled() {
  std::vector<int> v{3, 9, 4};
  for (auto& x : v) x *= 3;
  int m = 0;
  for (int x : v)
    if (x > m) m = x;
  return m;
}
static_assert(max_tripled() == 27);
int main() { std::println("{}", max_tripled()); }

